package com.nextgen.gameaggregator.vendor.aviatrix.api.promowin;

import com.nextgen.gameaggregator.enums.BetStatus;
import com.nextgen.gameaggregator.operator.wallet.settled.BetResultData;
import jakarta.validation.constraints.Digits;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;
import lombok.Data;

import java.math.BigDecimal;
import java.math.BigInteger;
import java.math.RoundingMode;

@Data
public class PromoWinDto implements BetResultData {
    @NotBlank
    @Size(max = 255)
    private String cid; //channel id generated by vendor for identification

    @NotBlank
    @Size(max = 255)
    private String sessionToken;

    @NotBlank
    @Size(max = 50)
    private String playerId; //vendor player id

    @NotBlank
    @Size(max = 255)
    private String productId; // game id

    @NotBlank
    @Size(max = 255)
    private String txId; // transaction id, unique for every transaction

    @NotNull
    @Digits(integer = 20, fraction = 0)
    private BigInteger amount; //bet amount

    @NotBlank
    @Size(max = 5)
    private String currency; //currency used

    @Override
    public String getExternalTransactionId() {
        return this.txId;
    }

    @Override
    public String getVendorBetId() {
        return this.txId;
    }

    @Override
    public String getRoundId() {
        return this.txId;
    }

    @Override
    public String getGameId() {
        return this.productId;
    }

    @Override
    public BigDecimal getBetAmount() {
        return null;
    }

    @Override
    public BigDecimal getWinAmount() {
        return new BigDecimal(this.amount).divide(BigDecimal.valueOf(100), 2, RoundingMode.DOWN);
    }

    @Override
    public BigDecimal getWinLoss() {
        return null;
    }

    @Override
    public BigDecimal getEffectiveTurnover() {
        return null;
    }

    @Override
    public Long getVendorBetTime() {
        return null;
    }

    @Override
    public Long getResultTime() {
        return System.currentTimeMillis();
    }

    @Override
    public Long getVendorSettleTime() {
        return System.currentTimeMillis();
    }

    @Override
    public BigDecimal getJackpotAmount() {
        return null;
    }

    @Override
    public Integer getIsFreespin() {
        return null;
    }

    @Override
    public BetStatus getBetStatus() {
        return BetStatus.SETTLED;
    }
}
